import { ClassNames } from "../shared/domNames";
import { ExpandedLiveValue } from "./lib/liveValue/expanded";
import type { LiveValueInterface } from "./lib/liveValue/interface";
import { context } from "./lib/liveValueContext/liveValueContext";

type MakeInteractionContainerInteractiveParams = {
  container: HTMLElement | null;
  viewer: HTMLElement | null;
  controlFullscreen: HTMLButtonElement | null;
  controlExpand: HTMLButtonElement | null;
};
type MakeInteractionContainerInteractiveReturn = {
  isFullscreen: LiveValueInterface<boolean>;
  isExpanded: LiveValueInterface<boolean>;
};
export const makeInteractionContainerInteractive = ({
  container,
  viewer,
  controlFullscreen,
  controlExpand,
}: MakeInteractionContainerInteractiveParams): MakeInteractionContainerInteractiveReturn => {
  const isFullscreenSetter = ExpandedLiveValue.new(false);
  const { value: isFullscreen } = isFullscreenSetter;
  const isExpandedSetter = ExpandedLiveValue.new(false);
  const { value: isExpanded } = isExpandedSetter;

  if (viewer) {
    const isViewerFullscreen = () => document.fullscreenElement === viewer;
    viewer.addEventListener("fullscreenchange", () => {
      isFullscreenSetter.setIfNew(isViewerFullscreen());
    });
    isFullscreenSetter.setIfNew(isViewerFullscreen());

    if (controlFullscreen) {
      context.observe(isFullscreen, (isFullscreen) => {
        controlFullscreen.classList.toggle(ClassNames.ACTIVE, isFullscreen);
      });
      controlFullscreen.addEventListener("click", () => {
        if (isFullscreen.value) {
          document.exitFullscreen().catch(() => {
            // Do nothing
          });
        } else {
          viewer.requestFullscreen().catch(() => {
            // Do nothing
          });
        }
      });
    }

    if (controlExpand) {
      context.observe(isFullscreen, (isFullscreen) => {
        controlExpand.disabled = isFullscreen;
      });
    }
  }

  if (controlExpand) {
    controlExpand.addEventListener("click", () => {
      isExpandedSetter.set(!isExpanded.value);
    });
    context.observe(isExpanded, (isExpanded) => {
      controlExpand.classList.toggle(ClassNames.ACTIVE, isExpanded);
    });

    if (container) {
      context.observe(isExpanded, (isExpanded) => {
        container.classList.toggle(ClassNames.EXPANDED, isExpanded);
        if (isExpanded) {
          viewer?.scrollIntoView({ block: "center" });
        }
      });
    }
  }

  return {
    isFullscreen,
    isExpanded,
  };
};
