import { LiveValuePair, type LiveValue } from "./lib/liveValue/liveValue";

type AttachDragTrackerReturn = {
  dragging: LiveValue<null, LiveValue<Coords> | null>;
};
export const attachDragTracker = (
  surface: HTMLElement,
): AttachDragTrackerReturn => {
  const { value: dragging, setter: draggingSetter } =
    LiveValuePair.null<LiveValue<Coords> | null>();

  let isDragging = false;
  let onPointerMove: (event: PointerEvent) => void = () => {
    // Do nothing
  };
  let onPointerUp: (event: PointerEvent) => void = () => {
    // Do nothing
  };
  const cleanup = () => {
    surface.removeEventListener("pointermove", onPointerMove);
    surface.removeEventListener("pointerup", onPointerUp);
    surface.removeEventListener("pointercancel", onPointerUp);
    isDragging = false;
    draggingSetter.set(null);
  };

  surface.addEventListener("pointerdown", (event: PointerEvent) => {
    if (isDragging) {
      cleanup();
    }

    const { value: coords, setter: coordsSetter } = LiveValuePair.new(
      new Coords(0, 0),
    );
    const pointerId = event.pointerId;
    const startX = event.clientX;
    const startY = event.clientY;

    onPointerMove = (event: PointerEvent) => {
      if (event.pointerId !== pointerId) {
        return;
      }

      coordsSetter.set(
        new Coords(event.clientX - startX, event.clientY - startY),
      );
    };
    surface.addEventListener("pointermove", onPointerMove);

    onPointerUp = (event: PointerEvent) => {
      if (event.pointerId !== pointerId) {
        return;
      }

      coordsSetter.set(
        new Coords(event.clientX - startX, event.clientY - startY),
      );
      cleanup();
    };
    surface.addEventListener("pointerup", onPointerUp);
    surface.addEventListener("pointercancel", onPointerUp);

    surface.setPointerCapture(event.pointerId);
    isDragging = true;
    draggingSetter.set(coords);
  });

  return { dragging };
};

class Coords {
  constructor(
    readonly deltaX: number,
    readonly deltaY: number,
  ) {}
}
