import type { Entry } from "./entry";
import { makeEntrySelectorInteractive } from "./entrySelectorComponent";
import { makeFpvInteractive } from "./fpvComponent";

type MakeEntriesInteractiveParams = {
  entriesWithDom: { entry: Entry; radioButton: HTMLInputElement | null }[];
  fpvContainer: HTMLElement | null;
  fpvViewer: HTMLElement | null;
  fpvSurface: HTMLCanvasElement | null;
  fpvControlFullscreen: HTMLButtonElement | null;
  fpvControlExpand: HTMLButtonElement | null;
  fpvControlZoomIn: HTMLButtonElement | null;
  fpvControlZoomOut: HTMLButtonElement | null;
};
export const makeEntriesInteractive = ({
  entriesWithDom,
  fpvContainer,
  fpvViewer,
  fpvSurface,
  fpvControlFullscreen,
  fpvControlExpand,
  fpvControlZoomIn,
  fpvControlZoomOut,
}: MakeEntriesInteractiveParams): void => {
  const { activeEntry } = makeEntrySelectorInteractive({
    entriesWithDom,
  });

  makeFpvInteractive({
    container: fpvContainer,
    viewer: fpvViewer,
    controlFullscreen: fpvControlFullscreen,
    controlExpand: fpvControlExpand,
    controlZoomIn: fpvControlZoomIn,
    controlZoomOut: fpvControlZoomOut,
    surface: fpvSurface,
    activeEntry,
  });
};
