export class KeyHandlerMap {
  readonly codes = new Map<string, (event: KeyboardEvent) => void>();
  readonly keys = new Map<string, (event: KeyboardEvent) => void>();

  private constructor() {
    // Private constructor
  }

  static new() {
    return new KeyHandlerMap();
  }

  processEvent(event: KeyboardEvent): void {
    this.codes.get(event.code)?.(event);
    this.keys.get(event.key)?.(event);
  }
}
