import {
  AppendableList,
  type ListAppender,
  type ListIterable,
  type Remover,
} from "../appendableList/appendableList";
import type {
  ObserverInterface,
  EventReceiverInterface,
  SimpleEventReceiverInterface,
} from "../event/interface";
import { ExpandedLiveValue } from "../liveValue/expanded";
import type { LiveValueInterface } from "../liveValue/interface";
import { noOpObserver } from "../observer/noOpObserver";

export class ContextPair<Observer> {
  readonly manager: ContextManager;
  readonly context: Context<Observer>;

  private constructor(observer: Observer) {
    const state: State = new State();
    const { iterable, appender } = AppendableList.new<ObserverInterface>();
    this.context = new Context(observer, state, appender);
    this.manager = new ContextManager(state, iterable);
  }

  static new<Observer extends ObserverInterface>(
    observer: Observer,
  ): ContextPair<Observer> {
    return new ContextPair(observer);
  }

  static root(): ContextPair<null> {
    return new ContextPair<null>(null);
  }
}

class Context<Observer> {
  constructor(
    public readonly observer: Observer,
    private readonly state: State,
    private readonly appender: ListAppender<ObserverInterface>,
  ) {}

  linkObserver(observer: ObserverInterface): ObserverInterface {
    if (!this.state.active) {
      observer.stop();
      return noOpObserver;
    }

    const remover = this.appender.append(observer);
    return new ObserverObserver(observer, remover);
  }

  listen<Value>(
    receiver: EventReceiverInterface<Value>,
    handler: (value: Value, context: Context<ObserverInterface>) => void,
  ): ObserverInterface {
    if (!this.state.active) {
      return noOpObserver;
    }

    const contextManagerObserver = new ContextManagerObserver(
      new NoOpContextManager(),
    );
    const observer = receiver.listen((value) => {
      contextManagerObserver.manager.stop();
      const { context, manager } = ContextPair.new(observer);
      contextManagerObserver.manager = manager;

      handler(value, context);
    });

    const remover = this.appender.append(observer);
    const contextManagerRemover = this.appender.append(contextManagerObserver);
    return new OnSetObserver(
      observer,
      remover,
      contextManagerObserver,
      contextManagerRemover,
    );
  }

  simpleListen(
    receiver: SimpleEventReceiverInterface,
    handler: (context: Context<ObserverInterface>) => void,
  ): ObserverInterface {
    if (!this.state.active) {
      return noOpObserver;
    }

    const contextManagerObserver = new ContextManagerObserver(
      new NoOpContextManager(),
    );
    const observer = receiver.listen(() => {
      contextManagerObserver.manager.stop();
      const { context, manager } = ContextPair.new(observer);
      contextManagerObserver.manager = manager;

      handler(context);
    });

    const remover = this.appender.append(observer);
    const contextManagerRemover = this.appender.append(contextManagerObserver);
    return new OnSetObserver(
      observer,
      remover,
      contextManagerObserver,
      contextManagerRemover,
    );
  }

  onSet<Value>(
    liveValue: LiveValueInterface<unknown, Value>,
    handler: (value: Value, context: Context<ObserverInterface>) => void,
  ): ObserverInterface {
    return this.listen(liveValue.updates, handler);
  }

  observe<InitialValue, Value = InitialValue>(
    liveValue: LiveValueInterface<InitialValue, Value>,
    handler: (
      value: InitialValue | Value,
      context: Context<ObserverInterface>,
    ) => void,
  ): ObserverInterface {
    if (!this.state.active) {
      return noOpObserver;
    }

    const contextManagerObserver = new ContextManagerObserver(
      new NoOpContextManager(),
    );
    const updatesObserver = liveValue.updates.listen((value) => {
      contextManagerObserver.manager.stop();
      const { context, manager } = ContextPair.new<ObserverInterface>(observer);
      contextManagerObserver.manager = manager;

      handler(value, context);
    });

    const updatesRemover = this.appender.append(updatesObserver);
    const contextManagerRemover = this.appender.append(contextManagerObserver);
    const observer = new OnSetObserver(
      updatesObserver,
      updatesRemover,
      contextManagerObserver,
      contextManagerRemover,
    );

    const { context, manager } = ContextPair.new<ObserverInterface>(observer);
    contextManagerObserver.manager = manager;

    handler(liveValue.value, context);

    return observer;
  }

  transform<
    InitialTransform,
    InitialValue,
    Transform = InitialTransform,
    Value = InitialValue,
  >(
    liveValue: LiveValueInterface<InitialValue, Value>,
    handlerCreator: (
      child: ExpandedLiveValue<InitialTransform, Transform>,
    ) => (
      value: InitialValue | Value,
      context: Context<ObserverInterface>,
    ) => void,
    initialValue: InitialTransform,
  ): LiveValueInterface<InitialTransform, Transform> {
    const child = ExpandedLiveValue.new<InitialTransform, Transform>(
      initialValue,
    );
    if (!this.state.active) {
      return child.value;
    }

    const handler = handlerCreator(child);
    this.observe(liveValue, handler);
    return child.value;
  }
}

type ContextManagerInterface = {
  stop(): void;
};

class ContextManager implements ContextManagerInterface {
  private iterable: ListIterable<ObserverInterface> | null;

  constructor(
    private readonly state: State,
    iterable: ListIterable<ObserverInterface>,
  ) {
    this.iterable = iterable;
  }

  stop() {
    this.state.active = false;
    const iterable = this.iterable;
    if (iterable) {
      this.iterable = null;
      iterable.every((observable: ObserverInterface) => {
        observable.stop();
        return true;
      });
    }
  }
}

class NoOpContextManager implements ContextManagerInterface {
  stop() {
    // Do nothing
  }
}

class State {
  active = true;
}

class ObserverObserver implements ObserverInterface {
  constructor(
    private readonly observer: ObserverInterface,
    private readonly remover: Remover,
  ) {}

  stop(): void {
    this.remover.remove();
    this.observer.stop();
  }
}

class OnSetObserver implements ObserverInterface {
  constructor(
    private readonly updatesObserver: ObserverInterface,
    private readonly updatesRemover: Remover,
    private readonly contextManagerObserver: ContextManagerObserver,
    private readonly contextManagerRemover: Remover,
  ) {}

  stop(): void {
    this.updatesRemover.remove();
    this.contextManagerRemover.remove();
    this.updatesObserver.stop();
    this.contextManagerObserver.stop();
  }
}

class ContextManagerObserver implements ObserverInterface {
  constructor(public manager: ContextManagerInterface) {}

  stop() {
    this.manager.stop();
  }
}

export const context: Context<null> = ContextPair.root().context;

export type { Context };
