import {
  AppendableList,
  type ListAppender,
  type ListIterable,
  type Remover,
} from "../appendableList/appendableList";
import type {
  EventChannelInterface,
  EventReceiverInterface,
  EventSenderInterface,
  ObserverInterface,
  SimpleEventChannelInterface,
  SimpleEventReceiverInterface,
  SimpleEventSenderInterface,
} from "./interface";

export class Channel<Value> implements EventChannelInterface<Value> {
  readonly receiver: Receiver<Value>;
  readonly sender: Sender<Value>;

  private constructor() {
    const { iterable, appender } = AppendableList.new<(value: Value) => void>();
    this.receiver = new Receiver(appender);
    this.sender = new Sender(iterable);
  }

  static new<Value>(): Channel<Value> {
    return new Channel<Value>();
  }
}

class Receiver<Value> implements EventReceiverInterface<Value> {
  constructor(
    private readonly appender: ListAppender<(value: Value) => void>,
  ) {}

  listen(handler: (value: Value) => void): Observer {
    const remover = this.appender.append(handler);
    return new Observer(remover);
  }
}

class Sender<Value> implements EventSenderInterface<Value> {
  private active = false;

  constructor(
    private readonly iterable: ListIterable<(value: Value) => void>,
  ) {}

  send(value: Value): void {
    this.active = true;
    this.iterable.every((handler) => {
      handler(value);
      return this.active;
    });
    this.active = false;
  }

  bookkeep(): void {
    if (this.active) {
      return;
    }

    this.iterable.markAppendedAsIterable();
  }
}

class Observer implements ObserverInterface {
  constructor(private readonly remover: Remover) {}

  stop(): void {
    this.remover.remove();
  }
}

export class SimpleChannel implements SimpleEventChannelInterface {
  readonly receiver: SimpleReceiver;
  readonly sender: SimpleSender;

  private constructor(channel: Channel<null>) {
    this.receiver = new SimpleReceiver(channel.receiver);
    this.sender = new SimpleSender(channel.sender);
  }

  static new(): SimpleChannel {
    return new SimpleChannel(Channel.new<null>());
  }
}

class SimpleReceiver implements SimpleEventReceiverInterface {
  constructor(private readonly receiver: Receiver<null>) {}

  listen(handler: () => void): Observer {
    return this.receiver.listen(() => {
      handler();
    });
  }
}

class SimpleSender implements SimpleEventSenderInterface {
  constructor(private readonly sender: Sender<null>) {}

  send(): void {
    this.sender.send(null);
  }

  bookkeep(): void {
    this.sender.bookkeep();
  }
}

export type {
  EventChannelInterface,
  EventReceiverInterface,
  EventSenderInterface,
  ObserverInterface,
  SimpleEventChannelInterface,
  SimpleEventReceiverInterface,
  SimpleEventSenderInterface,
  Observer,
  Receiver,
  Sender,
  SimpleReceiver,
  SimpleSender,
};
