import type {
  LiveValueInterface,
  LiveValuePairInterface,
  SetterInterface,
} from "./interface";
import { LiveValuePair } from "./liveValue";

export class ExpandedLiveValue<InitialValue, Value = InitialValue>
  implements LiveValuePairInterface<InitialValue, Value>, SetterInterface<Value>
{
  readonly value: LiveValueInterface<InitialValue, Value>;
  readonly setter: SetterInterface<Value>;

  private constructor({
    value,
    setter,
  }: LiveValuePairInterface<InitialValue, Value>) {
    this.value = value;
    this.setter = setter;
  }

  static fromLiveValuePair<InitialValue, Value = InitialValue>(
    liveValuePair: LiveValuePairInterface<InitialValue, Value>,
  ): ExpandedLiveValue<InitialValue, Value> {
    return new ExpandedLiveValue(liveValuePair);
  }

  static new<InitialValue, Value = InitialValue>(
    initialValue: InitialValue,
  ): ExpandedLiveValue<InitialValue, Value> {
    return ExpandedLiveValue.fromLiveValuePair<InitialValue, Value>(
      LiveValuePair.new<InitialValue, Value>(initialValue),
    );
  }

  static null<Value>(): ExpandedLiveValue<null, Value> {
    return ExpandedLiveValue.fromLiveValuePair<null, Value>(
      LiveValuePair.null<Value>(),
    );
  }

  static undefined<Value>(): ExpandedLiveValue<undefined, Value> {
    return ExpandedLiveValue.fromLiveValuePair<undefined, Value>(
      LiveValuePair.undefined<Value>(),
    );
  }

  set(value: Value): void {
    this.setter.set(value);
  }

  setIfNew(value: Value): void {
    if (value !== this.value.value) {
      this.setter.set(value);
    }
  }
}

export type { LiveValueInterface, LiveValuePairInterface, SetterInterface };
