import { Channel, type Receiver, type Sender } from "../event/event";
import type {
  LiveValueInterface,
  LiveValuePairInterface,
  SetterInterface,
} from "./interface";

export class LiveValuePair<InitialValue, Value = InitialValue>
  implements LiveValuePairInterface<InitialValue, Value>
{
  readonly value: LiveValue<InitialValue, Value>;
  readonly setter: Setter<Value>;

  private constructor(initialValue: InitialValue) {
    const { receiver, sender } = Channel.new<Value>();
    const value = new LiveValueInternal(initialValue, receiver);
    this.value = value;
    this.setter = new Setter(value, sender);
  }

  static new<InitialValue, Value = InitialValue>(
    initialValue: InitialValue,
  ): LiveValuePair<InitialValue, Value> {
    return new LiveValuePair<InitialValue, Value>(initialValue);
  }

  static null<Value>(): LiveValuePair<null, Value> {
    return new LiveValuePair<null, Value>(null);
  }

  static undefined<Value>(): LiveValuePair<undefined, Value> {
    return new LiveValuePair<undefined, Value>(undefined);
  }
}

export type LiveValue<InitialValue, Value = InitialValue> = LiveValueInterface<
  InitialValue,
  Value
> & {
  readonly value: InitialValue | Value;
  readonly updates: Receiver<Value>;
};

class LiveValueInternal<InitialValue, Value>
  implements LiveValue<InitialValue, Value>
{
  value: InitialValue | Value;

  constructor(
    value: InitialValue,
    readonly updates: Receiver<Value>,
  ) {
    this.value = value;
  }
}

class Setter<Value> implements SetterInterface<Value> {
  constructor(
    private readonly liveValue: LiveValueInternal<unknown, Value>,
    private readonly updatesSender: Sender<Value>,
  ) {}

  set(value: Value): void {
    this.liveValue.value = value;
    this.updatesSender.send(value);
  }
}

export type { LiveValueInterface, LiveValuePairInterface, SetterInterface };
