import { ClassNames } from "../shared/domNames";
import { attachDirectionTracking } from "./directionControlsTracker";
import { attachDragTracker } from "./dragTracker";
import type { Entry } from "./entry";
import { makeFpvCanvasInteractive } from "./fpvCanvasComponent";
import { makeInteractionContainerInteractive } from "./interactionContainer";
import { blurActiveElement, setDisableAndMaybeRefocus } from "./lib/dom/util";
import { ExpandedLiveValue } from "./lib/liveValue/expanded";
import type { LiveValueInterface } from "./lib/liveValue/interface";
import { LiveValuePair } from "./lib/liveValue/liveValue";
import { context } from "./lib/liveValueContext/liveValueContext";
import { clamp } from "./lib/math";
import {
  MAX_FOCAL,
  MAX_THETA,
  MIN_FOCAL,
  MIN_THETA,
  RenderState,
} from "./renderState";

// Rate in radians / ms
const PSI_RATE = Math.PI / 2 / 1000;
const THETA_RATE = Math.PI / 2 / 1000;
const FOCAL_RATE = 3 / 1000;

// Rate in radians / ms
const PSI_BOOST_RATE = PSI_RATE * 2;
const THETA_BOOST_RATE = THETA_RATE * 2;
const FOCAL_BOOST_RATE = FOCAL_RATE * 2;

const FOCAL_STEP = 1;

type MakeFpvInteractiveParams = {
  container: HTMLElement | null;
  viewer: HTMLElement | null;
  surface: HTMLCanvasElement | null;
  controlFullscreen: HTMLButtonElement | null;
  controlExpand: HTMLButtonElement | null;
  controlZoomIn: HTMLButtonElement | null;
  controlZoomOut: HTMLButtonElement | null;
  activeEntry: LiveValueInterface<null, Entry>;
};
export const makeFpvInteractive = ({
  container,
  viewer,
  controlFullscreen,
  controlExpand,
  controlZoomIn,
  controlZoomOut,
  surface,
  activeEntry,
}: MakeFpvInteractiveParams): void => {
  const { isFullscreen } = makeInteractionContainerInteractive({
    container,
    viewer,
    controlFullscreen,
    controlExpand,
  });

  if (!surface) {
    return;
  }

  const { value: renderState, setter: renderStateSetter } = LiveValuePair.new(
    RenderState.default(),
  );
  const isAnimatingSetter = ExpandedLiveValue.new(false);
  const { value: isAnimating } = isAnimatingSetter;
  let renderTimeStamp = 0;

  const { renderReceiver, isViewActive } = makeFpvCanvasInteractive({
    canvas: surface,
    activeEntry,
    renderState,
    isAnimating,
  });
  const { dragging } = attachDragTracker(surface);

  const setRenderState = (
    renderState: RenderState,
    timeStamp = performance.now(),
  ) => {
    renderStateSetter.set(renderState);
    renderTimeStamp = timeStamp;
  };

  context.onSet(isViewActive, (isViewActive) => {
    if (!isViewActive) {
      setRenderState(RenderState.default());
    }
  });

  const zoomIn = () => {
    const currentRenderState = renderState.value;
    setRenderState(
      RenderState.new(
        currentRenderState.psi,
        currentRenderState.theta,
        limitFocal(currentRenderState.focal + FOCAL_STEP),
      ),
    );
  };
  const zoomOut = () => {
    const currentRenderState = renderState.value;
    setRenderState(
      RenderState.new(
        currentRenderState.psi,
        currentRenderState.theta,
        limitFocal(currentRenderState.focal - FOCAL_STEP),
      ),
    );
  };

  if (viewer) {
    viewer.addEventListener("wheel", (event) => {
      if (isFullscreen.value || viewer.contains(document.activeElement)) {
        const { deltaY } = event;
        if (deltaY !== 0) {
          if (deltaY < 0) {
            zoomIn();
          } else {
            zoomOut();
          }
          event.preventDefault();
        }
      }
    });

    const { vectors, keyDownMap } = attachDirectionTracking(viewer);

    keyDownMap.keys.set("Escape", () => {
      blurActiveElement();
    });

    keyDownMap.keys.set(" ", (event) => {
      event.preventDefault();
      setRenderState(RenderState.default(), event.timeStamp);
    });

    context.observe(isViewActive, (isViewActive, context) => {
      if (!isViewActive) {
        isAnimatingSetter.setIfNew(false);
        return;
      }

      context.observe(dragging, (dragging, context) => {
        if (dragging) {
          isAnimatingSetter.setIfNew(false);
          return;
        }

        let lastVectors = vectors.value;
        renderTimeStamp = lastVectors.isActive() ? performance.now() : 0;
        const tick = (timeStamp: DOMHighResTimeStamp) => {
          if (lastVectors.isActive()) {
            const currentRenderState = renderState.value;
            setRenderState(
              RenderState.new(
                currentRenderState.psi +
                  interpolate(lastVectors.x, renderTimeStamp, timeStamp) *
                    (lastVectors.shift ? PSI_BOOST_RATE : PSI_RATE),
                limitTheta(
                  currentRenderState.theta +
                    interpolate(lastVectors.y, renderTimeStamp, timeStamp) *
                      (lastVectors.shift ? THETA_BOOST_RATE : THETA_RATE),
                ),
                limitFocal(
                  currentRenderState.focal +
                    interpolate(lastVectors.z, renderTimeStamp, timeStamp) *
                      (lastVectors.shift ? FOCAL_BOOST_RATE : FOCAL_RATE),
                ),
              ),
              timeStamp,
            );
          } else {
            renderTimeStamp = timeStamp;
          }
        };
        context.onSet(vectors, (vectors) => {
          tick(vectors.timeStamp);
          lastVectors = vectors;
        });
        context.observe(vectors, (vectors, context) => {
          const active = vectors.isActive();
          if (active) {
            context.listen(renderReceiver, (timeStamp) => {
              tick(timeStamp);
            });
          }
          isAnimatingSetter.setIfNew(active);
        });
      });
    });
  }

  context.observe(dragging, (dragging, context) => {
    surface.classList.toggle(ClassNames.DRAGGING, !!dragging);
    if (dragging) {
      const renderStateStart = renderState.value;
      const focal = renderStateStart.focal;
      const surfaceWidth = surface.clientWidth;
      const surfaceHeight = surface.clientHeight;
      context.observe(dragging, (coords) => {
        renderStateSetter.set(
          RenderState.new(
            renderStateStart.psi + (coords.deltaX / surfaceWidth / focal) * -3,
            limitTheta(
              renderStateStart.theta +
                (coords.deltaY / surfaceHeight / focal) * 2,
            ),
            focal,
          ),
        );
      });
    }
  });

  surface.addEventListener("dblclick", (_event) => {
    zoomIn();
  });

  if (controlZoomIn) {
    controlZoomIn.addEventListener("click", (_event) => {
      zoomIn();
    });

    const isMaxZoom = context.transform(
      renderState,
      (setter) => (renderState) => {
        setter.setIfNew(renderState.focal >= MAX_FOCAL);
      },
      false,
    );
    context.observe(isMaxZoom, (isMaxZoom) => {
      setDisableAndMaybeRefocus(controlZoomIn, isMaxZoom, viewer);
    });
  }

  if (controlZoomOut) {
    controlZoomOut.addEventListener("click", (_event) => {
      zoomOut();
    });

    const isMinZoom = context.transform(
      renderState,
      (setter) => (renderState) => {
        setter.setIfNew(renderState.focal <= MIN_FOCAL);
      },
      false,
    );
    context.observe(isMinZoom, (isMinZoom) => {
      setDisableAndMaybeRefocus(controlZoomOut, isMinZoom, viewer);
    });
  }
};

const limitTheta = (theta: number) => clamp(theta, MIN_THETA, MAX_THETA);

const limitFocal = (focal: number) => clamp(focal, MIN_FOCAL, MAX_FOCAL);

const interpolate = (
  magnitude: number,
  startTimeStamp: DOMHighResTimeStamp,
  timeStamp: DOMHighResTimeStamp,
) => magnitude * (timeStamp - startTimeStamp);
