import { KeyHandlerMap } from "./lib/dom/event/keyHandler";
import { ExpandedLiveValue } from "./lib/liveValue/expanded";
import type { LiveValueInterface } from "./lib/liveValue/interface";
import { LiveValuePair } from "./lib/liveValue/liveValue";
import { context } from "./lib/liveValueContext/liveValueContext";

const dimensionDefinitions = {
  x: {
    positive: ["ArrowRight", "KeyD", "Numpad6"],
    negative: ["ArrowLeft", "KeyA", "Numpad4"],
  },
  y: {
    positive: ["ArrowUp", "KeyW", "Numpad8"],
    negative: ["ArrowDown", "KeyS", "Numpad2"],
  },
  z: {
    positive: ["NumpadAdd", "KeyE"],
    negative: ["NumpadSubtract", "KeyQ"],
  },
};

type TrackDirectionCommandsReturn = {
  vectors: LiveValueInterface<VectorsState>;
  keyDownMap: KeyHandlerMap;
  keyUpMap: KeyHandlerMap;
  onFocusOut: (event: FocusEvent) => void;
};
export const trackDirectionCommands = (): TrackDirectionCommandsReturn => {
  const { value: vectors, setter: vectorsSetter } =
    LiveValuePair.new<VectorsState>(new MutableVectorsState(0, 0, 0, false, 0));
  const keyDownMap = KeyHandlerMap.new();
  const keyUpMap = KeyHandlerMap.new();

  const vectorsState = new MutableVectorsState(0, 0, 0, false, 0);
  const sendVectors = () => {
    vectorsSetter.set(
      new MutableVectorsState(
        vectorsState.x,
        vectorsState.y,
        vectorsState.z,
        vectorsState.shift,
        vectorsState.timeStamp,
      ),
    );
  };

  keyDownMap.keys.set("Shift", (event) => {
    if (vectorsState.shift) {
      return;
    }

    vectorsState.shift = true;
    vectorsState.timeStamp = event.timeStamp;
    sendVectors();
  });
  keyUpMap.keys.set("Shift", (event) => {
    if (!vectorsState.shift) {
      return;
    }

    vectorsState.shift = false;
    vectorsState.timeStamp = event.timeStamp;
    sendVectors();
  });

  const isKeyActiveSetters: ExpandedLiveValue<boolean>[] = [];
  for (const {
    def: { positive, negative },
    setter,
  } of [
    {
      def: dimensionDefinitions.x,
      setter: (x: number) => {
        vectorsState.x = x;
      },
    },
    {
      def: dimensionDefinitions.y,
      setter: (y: number) => {
        vectorsState.y = y;
      },
    },
    {
      def: dimensionDefinitions.z,
      setter: (z: number) => {
        vectorsState.z = z;
      },
    },
  ]) {
    let magnitude = 0;
    for (const { dir, codes } of [
      { dir: 1, codes: positive },
      { dir: -1, codes: negative },
    ]) {
      let activeKeyCount = 0;
      for (const code of codes) {
        const isKeyActiveSetter = ExpandedLiveValue.new(false);
        const { value: isKeyActive } = isKeyActiveSetter;

        context.onSet(isKeyActive, (isKeyActive) => {
          const wasZeroKeys = activeKeyCount === 0;
          activeKeyCount += isKeyActive ? 1 : -1;
          const isZeroKeys = activeKeyCount === 0;

          if (wasZeroKeys) {
            magnitude += dir;
          } else if (isZeroKeys) {
            magnitude -= dir;
          }

          if (wasZeroKeys || isZeroKeys) {
            setter(magnitude);
            sendVectors();
          }
        });

        keyDownMap.codes.set(code, (event: KeyboardEvent) => {
          event.preventDefault();
          vectorsState.timeStamp = event.timeStamp;
          isKeyActiveSetter.setIfNew(true);
        });
        keyUpMap.codes.set(code, (event: KeyboardEvent) => {
          vectorsState.timeStamp = event.timeStamp;
          isKeyActiveSetter.setIfNew(false);
        });
        isKeyActiveSetters.push(isKeyActiveSetter);
      }
    }
  }

  const onFocusOut = (event: FocusEvent) => {
    vectorsState.timeStamp = event.timeStamp;
    for (const isKeyActiveSetter of isKeyActiveSetters) {
      isKeyActiveSetter.setIfNew(false);
    }
  };

  return { vectors, keyDownMap, keyUpMap, onFocusOut };
};

export const attachDirectionTracking = (
  element: HTMLElement,
): TrackDirectionCommandsReturn => {
  const tracked = trackDirectionCommands();
  const { keyDownMap, keyUpMap, onFocusOut } = tracked;

  element.addEventListener("keydown", (event) => {
    keyDownMap.processEvent(event);
  });
  element.addEventListener("keyup", (event) => {
    keyUpMap.processEvent(event);
  });
  element.addEventListener("focusout", onFocusOut);

  return tracked;
};

type VectorsState = {
  readonly x: number;
  readonly y: number;
  readonly z: number;
  readonly shift: boolean;
  readonly timeStamp: DOMHighResTimeStamp;
  isActive(): boolean;
};
class MutableVectorsState implements VectorsState {
  constructor(
    public x: number,
    public y: number,
    public z: number,
    public shift: boolean,
    public timeStamp: DOMHighResTimeStamp,
  ) {}

  isActive() {
    return this.x !== 0 || this.y !== 0 || this.z !== 0;
  }
}
