export const DEFAULT_PSI = 0;
export const DEFAULT_THETA = 0;
export const DEFAULT_FOCAL = 1.75;

export const MAX_THETA = Math.PI / 2;
export const MIN_THETA = -MAX_THETA;
export const MAX_FOCAL = 6.75;
export const MIN_FOCAL = 1.75;

export class RenderState {
  private constructor(
    readonly psi: number,
    readonly theta: number,
    readonly focal: number,
  ) {}

  static new(psi: number, theta: number, focal: number): RenderState {
    return new RenderState(psi, theta, focal);
  }

  static default(): RenderState {
    return new RenderState(DEFAULT_PSI, DEFAULT_THETA, DEFAULT_FOCAL);
  }
}
