import type { Entry } from "./entry";
import { LiveValuePair, type LiveValue } from "./lib/liveValue/liveValue";
import { context } from "./lib/liveValueContext/liveValueContext";

export type MakeEntrySelectorInteractiveParams = {
  entriesWithDom: { entry: Entry; radioButton: HTMLInputElement | null }[];
};
export type MakeEntrySelectorInteractiveReturn = {
  activeEntry: LiveValue<null, Entry>;
};
export const makeEntrySelectorInteractive = ({
  entriesWithDom,
}: MakeEntrySelectorInteractiveParams): MakeEntrySelectorInteractiveReturn => {
  const { value: activeEntry, setter: activeEntrySetter } =
    LiveValuePair.null<Entry>();
  let initialActiveEntry = null;
  for (const { radioButton, entry } of entriesWithDom) {
    if (!radioButton) {
      continue;
    }

    radioButton.addEventListener("change", () => {
      activeEntrySetter.set(entry);
    });
    if (radioButton.checked) {
      initialActiveEntry = entry;
      activeEntrySetter.set(entry);
    }
  }

  for (const { entry } of entriesWithDom) {
    if (!initialActiveEntry) {
      entry.view.load();
    } else {
      if (entry === initialActiveEntry) {
        entry.view.load();
      } else {
        context.observe(initialActiveEntry.view.isReady, (isReady, context) => {
          if (isReady) {
            entry.view.load();
            context.observer.stop();
          }
        });
      }
    }
  }

  return {
    activeEntry,
  };
};
