import type {
  LiveValueInterface,
  SetterInterface,
} from "./lib/liveValue/interface";
import { LiveValuePair } from "./lib/liveValue/liveValue";
import { context } from "./lib/liveValueContext/liveValueContext";

export enum LoadState {
  BEFORE_LOADING,
  LOADING,
  LOADED,
  ERROR,
}

export class Entry {
  readonly view: LoadableImage;

  constructor(
    private readonly index: number,
    viewSrc: string,
  ) {
    this.view = new LoadableImage(viewSrc);

    context.observe(this.view.loadState, (loadState: LoadState) => {
      if (loadState === LoadState.ERROR) {
        console.warn(`View ${this.index} failed to load`);
      }
    });
  }
}

class LoadableImage {
  readonly image = new Image();
  readonly loadState: LiveValueInterface<LoadState>;
  readonly isReady: LiveValueInterface<boolean>;
  private readonly loadStateSetter: SetterInterface<LoadState>;

  constructor(private readonly src: string) {
    const { value: loadState, setter: loadStateSetter } = LiveValuePair.new(
      LoadState.BEFORE_LOADING,
    );
    this.loadState = loadState;
    this.isReady = context.transform(
      loadState,
      (setter) => (loadState: LoadState) => {
        setter.setIfNew(loadState === LoadState.LOADED);
      },
      false,
    );
    this.loadStateSetter = loadStateSetter;
  }

  load() {
    const loadState = this.loadState.value;
    if (loadState === LoadState.LOADED || loadState === LoadState.LOADING) {
      return;
    }

    if (loadState === LoadState.BEFORE_LOADING) {
      const onLoad = () => {
        this.loadStateSetter.set(LoadState.LOADED);
        this.image.removeEventListener("load", onLoad);
        this.image.removeEventListener("error", onError);
      };
      this.image.addEventListener("load", onLoad);

      const onError = () => {
        this.loadStateSetter.set(LoadState.ERROR);
      };
      this.image.addEventListener("error", onError);
    }

    this.loadStateSetter.set(LoadState.LOADING);
    this.image.src = this.src;
  }
}

export type { LoadableImage };
